SELECT CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1500 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(amount) AS total_amount, DENSE_RANK() OVER (ORDER BY SUM(amount) DESC) AS rnk FROM transactions WHERE merchant IN ('Amazon', 'Lazada', '7-Eleven') GROUP BY CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1500 THEN 'mid' ELSE 'low' END ORDER BY 3 DESC, total_amount DESC;
